from packaging.dependency_groups import DependencyGroupResolver
from packaging.requirements import Requirement


def dependency_group_lookup(dependency_groups: dict[str, list[str | dict[str, str]]], group: str) -> list[str]:
    """Lookup a dependency group name and return its parsed dependency data without resolving includes. dependency_groups: mapping of dependency group names to their dependencies, group: the name of the group to lookup."""
    try:
        resolver = DependencyGroupResolver(dependency_groups)
        result = resolver.lookup(group)
        # Convert the result to JSON-serializable format - return strings as they were originally
        parsed_result = []
        for item in result:
            if isinstance(item, str):
                parsed_result.append(item)
            elif hasattr(item, 'name') and hasattr(item, 'specifier'):
                # Handle Requirement objects - reconstruct the requirement string
                req_str = item.name
                if item.specifier:
                    req_str += str(item.specifier)
                if item.extras:
                    req_str += f"[{','.join(item.extras)}]"
                parsed_result.append(req_str)
            elif hasattr(item, 'name'):
                # Handle DependencyGroupInclude objects - return as string representation
                parsed_result.append(item.name)
            else:
                # Fallback for any other type
                parsed_result.append(str(item))
        return parsed_result
    except Exception as e:
        raise ValueError(f"Failed to lookup dependency group {group!r}: {str(e)}")

