from packaging.markers import prepare_environment


def prepare_marker_environment(environment: dict[str, str | list[str] | None] | None = None, context: str = "metadata") -> dict[str, str | list[str] | None]:
    """Prepare a reusable marker environment from a mapping. environment: Mapping containing keys and values to override the detected environment. Values must be strings, except for 'extras' and 'dependency_groups', which take sets of strings. 'extra' may also be a set of extra names. context: The context in which the marker is evaluated, which influences what marker names are considered valid. Accepted values are 'metadata' (for core metadata; default), 'lock_file', and 'requirement'."""
    if context not in ("metadata", "lock_file", "requirement"):
        raise ValueError(f"Invalid context: {context!r}. Must be one of 'metadata', 'lock_file', or 'requirement'.")

    if environment is not None:
        # Convert list values to sets for 'extras' and 'dependency_groups' as required by the library
        converted_env = {}
        for key, value in environment.items():
            if key in ("extras", "dependency_groups") and isinstance(value, list):
                converted_env[key] = set(value)
            elif key == "extra" and isinstance(value, list):
                converted_env[key] = set(value)
            else:
                converted_env[key] = value
        environment = converted_env

    try:
        result = prepare_environment(environment, context)
        # Convert sets back to lists for JSON serialization
        final_result = {}
        for key, value in result.items():
            if isinstance(value, set):
                final_result[key] = sorted(value)
            else:
                final_result[key] = value
        return final_result
    except Exception as e:
        raise ValueError(f"Failed to prepare marker environment: {str(e)}")

from packaging.metadata import Metadata
from typing import Any, Dict, List, Optional, Union


def metadata_from_raw(data: Any, validate: bool = True) -> Dict[str, Any]:
    """Create a Metadata instance from raw metadata.

    Args:
        data: Raw metadata to create the Metadata instance from
        validate: Whether to validate the metadata during creation

    Returns:
        Dictionary representation of the metadata

    Example:
        >>> metadata_from_raw({"Name": "example", "Version": "1.0"})
        {"name": "example", "version": "1.0"}
    """
    try:
        metadata_instance = Metadata.from_raw(data, validate=validate)
        # Convert to dictionary representation
        result = {}
        # Get all attributes that are typically present in metadata
        attrs_to_check = [
            "name", "version", "summary", "description", "license",
            "author", "author_email", "maintainer", "maintainer_email",
            "home_page", "download_url", "project_urls", "keywords",
            "platforms", "classifiers", "requires_dist", "provides_dist",
            "obsoletes_dist", "requires_python", "requires_external",
            "provides_extras", "description_content_type"
        ]

        for attr in attrs_to_check:
            try:
                value = getattr(metadata_instance, attr, None)
                if value is not None:
                    if isinstance(value, list):
                        result[attr] = list(value)
                    elif isinstance(value, dict):
                        result[attr] = dict(value)
                    else:
                        result[attr] = str(value)
            except Exception:
                # Skip attributes that cause issues
                continue

        return result
    except Exception as e:
        raise ValueError(f"Failed to create metadata from raw data: {str(e)}")

