import dataclasses


def pylock_to_dict(pylock_instance: Pylock) -> Dict[str, Any]:
    """Convert the Pylock instance to a TOML dictionary.

    Args:
        pylock_instance: A Pylock instance to convert to a TOML dictionary

    Returns:
        A dictionary representation of the Pylock instance

    Example:
        >>> pylock_to_dict(pylock_instance)  # doctest: +SKIP
        {'dependencies': [...], 'dev-dependencies': [...]}
    """
    try:
        # Use dataclasses.asdict directly since we know Pylock is a dataclass
        result = dataclasses.asdict(pylock_instance)

        # Ensure all values are JSON serializable
        def make_json_serializable(obj: Any) -> Any:
            if isinstance(obj, dict):
                return {key: make_json_serializable(value) for key, value in obj.items()}
            elif isinstance(obj, list):
                return [make_json_serializable(item) for item in obj]
            else:
                # For other types, convert to string if needed
                return str(obj) if not isinstance(obj, (str, int, float, bool, type(None))) else obj

        return make_json_serializable(result)
    except Exception as e:
        raise ValueError(f"Failed to convert Pylock instance to dictionary: {str(e)}") from e

