import re


def is_valid_pylock_path(path: str) -> bool:
    """Check if the given path is a valid pylock file path. path: The file path to check, e.g. '/project/pylock.toml' -> true."""
    _PYLOCK_FILE_NAME_RE = re.compile(r"pylock-\d+\.\d+\.\d+\.toml")

    if not isinstance(path, str):
        raise ValueError(f"invalid path: {path!r}")

    # Extract filename from path
    file_name = path.split('/')[-1].split('\\')[-1]

    return file_name == "pylock.toml" or bool(_PYLOCK_FILE_NAME_RE.fullmatch(file_name))

